"""
Deterministic Decision Engine: Generates science-backed, personalized recommendations
for low-emission daily routines, IAQ hacks, and sustainable community alternatives.
"""
from typing import Dict, Any, List
from backend.models.schemas import (
    AirQualityContext, HouseholdProfile, RecommendationResponse,
    RiskSummary, RoutineItem, IAQHackItem, SustainableAlternativeItem, DirectImpactItem,
    ActivityEvaluationResponse
)
from backend.services.impact_estimator import ImpactEstimator

NON_MEDICAL_DISCLAIMER = (
    "Non-Medical Guidance Disclaimer: The recommendations generated by this assistant are environmental resilience "
    "and indoor air quality guidelines based on public health and atmospheric science. They do not constitute formal medical "
    "advice, clinical diagnosis, or medical prescriptions. Individuals experiencing acute respiratory distress, severe chest "
    "tightness, or uncontrolled asthma attacks must seek immediate medical evaluation from certified healthcare professionals "
    "or emergency services."
)

class DecisionEngine:
    def __init__(self):
        self.estimator = ImpactEstimator()

    def generate_recommendations(
        self,
        aqi_ctx: AirQualityContext,
        profile: HouseholdProfile,
        user_question: str = ""
    ) -> RecommendationResponse:
        """Construct deterministic, highly tailored recommendations."""
        severity = aqi_ctx.severity_tier
        aqi = aqi_ctx.aqi
        pm2_5 = aqi_ctx.pm2_5
        has_vulnerable = len(profile.vulnerable_members) > 0

        # 1. Build Risk Summary
        risk_summary = self._build_risk_summary(severity, aqi, pm2_5, profile.vulnerable_members)

        # 2. Build Low-Emission Daily Routines
        routines = self._build_daily_routines(severity, profile)

        # 3. Build Indoor Air Quality Hacks
        iaq_hacks = self._build_iaq_hacks(severity, profile)

        # 4. Build Sustainable Alternatives
        alternatives = self._build_sustainable_alternatives(profile)

        # 5. Build Direct Impact Explanations
        direct_impacts = self._build_direct_impacts(profile, pm2_5)

        return RecommendationResponse(
            risk_summary=risk_summary,
            daily_routines=routines,
            iaq_hacks=iaq_hacks,
            sustainable_alternatives=alternatives,
            direct_impacts=direct_impacts,
            generated_by="deterministic_engine",
            cached=False
        )

    def _build_risk_summary(
        self,
        severity: str,
        aqi: int,
        pm2_5: float,
        vulnerabilities: List[str]
    ) -> RiskSummary:
        vuln_tags = ", ".join(vulnerabilities).title() if vulnerabilities else "General Population"
        
        if severity == "Severe":
            health_warning = (
                f"🚨 CRITICAL EMERGENCY: AQI is {aqi} (PM2.5: {pm2_5} µg/m³). Outdoor air is hazardous to ALL individuals. "
                f"Extreme health risk for {vuln_tags} due to severe alveolar inflammation, airway constriction, and cardiovascular stress."
            )
            priority_actions = [
                "Strict outdoor curfew: Cancel all morning/evening outdoor walks, jogs, and unnecessary travel.",
                "Create a sealed 'Clean Air Sanctuary' room inside the home immediately.",
                "Ensure vulnerable individuals (children, asthmatics, seniors) remain in the filtered sanctuary.",
                "Fit certified N95/FFP2 respirators with proper facial seal if any emergency transit is mandatory."
            ]
        elif severity == "Very Poor":
            health_warning = (
                f"⚠️ HIGH RISK: AQI is {aqi} (PM2.5: {pm2_5} µg/m³). High risk of respiratory irritation, eye stinging, and bronchial flare-ups, "
                f"especially for {vuln_tags}."
            )
            priority_actions = [
                "Relocate all physical workouts and children's sports indoors.",
                "Keep windows and exterior doors firmly sealed during morning temperature inversion (05:00–10:00).",
                "Wear an N95 respirator during unavoidable commutes; avoid open two-wheeler travel.",
                "Run air filtration / DIY Corsi-Rosenthal cleaners continuously in occupied bedrooms."
            ]
        elif severity == "Poor":
            health_warning = (
                f"⚠️ UNHEALTHY FOR SENSITIVE GROUPS: AQI is {aqi} (PM2.5: {pm2_5} µg/m³). Sensitive individuals ({vuln_tags}) "
                f"may experience cough, throat scratchiness, and shortness of breath."
            )
            priority_actions = [
                "Sensitive individuals should avoid strenuous outdoor physical exertion.",
                "Time outdoor errands and ventilation strictly between 12:00 PM and 3:30 PM.",
                "Employ damp-cleaning protocols to keep indoor settled particulate under control."
            ]
        else: # Moderate
            health_warning = (
                f"ℹ️ MODERATE AIR QUALITY: AQI is {aqi} (PM2.5: {pm2_5} µg/m³). Generally acceptable, but highly sensitive persons "
                f"should monitor symptoms."
            )
            priority_actions = [
                "Favorable window for outdoor activities and home ventilation during peak afternoon sunlight.",
                "Maintain low-emission transport habits to keep neighborhood airshed clean."
            ]

        return RiskSummary(
            severity_tier=severity,
            aqi=aqi,
            pm2_5=pm2_5,
            health_warning=health_warning,
            priority_actions=priority_actions,
            non_medical_disclaimer=NON_MEDICAL_DISCLAIMER
        )

    def _build_daily_routines(self, severity: str, profile: HouseholdProfile) -> List[RoutineItem]:
        routines: List[RoutineItem] = []

        # Morning Routine
        if severity in ["Severe", "Very Poor"]:
            routines.append(RoutineItem(
                time_window="05:30 – 09:30 (Morning Inversion Peak)",
                title="Morning Inversion Lockdown & Indoor Routine Shift",
                description=(
                    "Severe thermal inversion traps ground-level emissions into a stagnant toxic blanket. "
                    "Keep all external doors and windows firmly sealed. Cancel morning outdoor walks, jogging, or outdoor school assemblies. "
                    "Practice indoor light stretching instead. Use electric kettle or covered boiling for breakfast preparation to prevent indoor steam/soot build-up."
                ),
                action_category="physical_activity",
                direct_impact="Avoids inhaling 4x higher particulate concentrations present in the early morning ground boundary layer."
            ))
        else:
            routines.append(RoutineItem(
                time_window="06:00 – 09:00 (Early Morning)",
                title="Low-Exertion Morning Schedule",
                description="Keep physical exertion moderate and close windows facing heavy traffic streets.",
                action_category="physical_activity",
                direct_impact="Protects airway mucosa from morning pollutant accumulation."
            ))

        # Commute Routine
        if profile.commute_mode in ["two_wheeler", "car_alone"]:
            routines.append(RoutineItem(
                time_window="08:00 – 10:00 (Commute Window)",
                title="Transit Mode & Protection Adjustment",
                description=(
                    "If traveling by two-wheeler, switch to enclosed metro/bus or carpool. If impossible, wear a tightly fitted N95 respirator "
                    "(cloth masks do NOT stop PM2.5). If driving alone, set cabin ventilation strictly to 'Recirculation Mode' to block tunnel/exhaust soot."
                ),
                action_category="commute",
                direct_impact="Recirculation mode cuts in-cabin PM2.5 by 65%; N95 filtration provides >95% aerosol protection."
            ))
        else:
            routines.append(RoutineItem(
                time_window="08:00 – 10:00 (Commute Window)",
                title="Transit Commute Resilience",
                description="Use underground or rapid bus corridors. Wear an N95 mask while waiting at surface bus stops.",
                action_category="commute",
                direct_impact="Saves 1.8 kg CO2e per round trip while bypassing roadway exhaust pockets."
            ))

        # Midday / Afternoon Routine
        if severity in ["Severe", "Very Poor"]:
            routines.append(RoutineItem(
                time_window="12:00 – 15:30 (Midday Boundary Layer Rise)",
                title="Controlled Micro-Ventilation & Essential Errands Window",
                description=(
                    "Solar heating causes the atmospheric mixing height to lift, dispersing ground contaminants. "
                    "If ventilation is necessary to reduce indoor CO2, open high-level or courtyard windows for no more than 15–20 minutes, "
                    "then re-seal and run air filtration. Complete essential outdoor errands during this lower-smog window."
                ),
                action_category="ventilation",
                direct_impact="Captures the daily trough in ambient PM2.5 concentrations while flushing stale CO2."
            ))
        else:
            routines.append(RoutineItem(
                time_window="12:00 – 15:00 (Midday Air Flushing)",
                title="Cross-Ventilation Window",
                description="Open opposite windows to promote fresh airflow during peak solar dilution hours.",
                action_category="ventilation",
                direct_impact="Reduces indoor volatile organic compounds (VOCs) and CO2 naturally."
            ))

        # Evening / Night Routine
        routines.append(RoutineItem(
            time_window="18:30 – 22:00 (Evening Re-Inversion & Sleep Prep)",
            title="Evening Re-Sealing & Bedroom Clean Sanctuary Prep",
            description=(
                "As the sun sets, surface temperatures drop, plunging the boundary layer and triggering evening rush-hour smog entrapment. "
                "Ensure all windows are shut before 17:30. Perform wet mopping in the bedroom 30 minutes before bedtime. "
                "Turn bedroom air purifier or DIY Corsi-Rosenthal fan to medium speed for uninterrupted overnight clean air."
            ),
            action_category="indoor_habits",
            direct_impact="Delivers 7–8 hours of low-PM2.5 restorative sleep, reducing nocturnal bronchospasm and morning headaches."
        ))

        return routines

    def _build_iaq_hacks(self, severity: str, profile: HouseholdProfile) -> List[IAQHackItem]:
        hacks: List[IAQHackItem] = []

        # 1. Zero Cost: Wet Mopping (Free)
        hacks.append(IAQHackItem(
            title="Damp Microfiber Mopping (The 0-Cost Particle Trap)",
            cost_tier="Free",
            materials_needed="Standard floor mop or cotton cloth, bucket of clean warm water.",
            implementation_steps=(
                "1. Strictly avoid dry broom sweeping, which flings settled PM2.5 and allergen particles into your breathing zone for hours.\n"
                "2. Mop floors with a damp microfiber or cotton cloth using gentle linear strokes.\n"
                "3. Rinse mop head in a separate bucket so collected soot is flushed away rather than redistributed."
            ),
            direct_impact="Cuts indoor particulate re-suspension by 70% without consuming electricity or requiring commercial chemicals."
        ))

        # 2. Zero Cost: Dedicated Clean Room Sanctuary (Free)
        hacks.append(IAQHackItem(
            title="Dedicated Clean Room Sanctuary Creation",
            cost_tier="Free",
            materials_needed="Central interior bedroom, towels, draft blockers, tape.",
            implementation_steps=(
                "1. Select the room with the fewest exterior-facing windows and doors (ideally where children or elderly sleep).\n"
                "2. Roll up bath towels or blankets and wedge them firmly into the gap beneath doors.\n"
                "3. Keep this sanctuary door closed 24/7; designate it as a no-shoe, no-smoke, and low-traffic zone."
            ),
            direct_impact="Creates an isolated indoor buffer zone with 40%–50% lower PM2.5 than the rest of the home."
        ))

        # 3. Low-Cost: DIY Corsi-Rosenthal Air Cleaner (< $15 - $25)
        hacks.append(IAQHackItem(
            title="DIY Corsi-Rosenthal Box Air Cleaner",
            cost_tier="Low-Cost (< $20)",
            materials_needed="Standard 20-inch box/table fan, 1 to 2 MERV-13 furnace filters (or HVAC filter sheets), duct tape, cardboard.",
            implementation_steps=(
                "1. Securely tape the MERV-13 filter to the intake side of the fan with airflow arrows pointing into the fan blades.\n"
                "2. Seal all side gaps with duct tape to ensure 100% of fan air is drawn through the filter fibers.\n"
                "3. Place in the center of the living area or bedroom on medium speed."
            ),
            direct_impact="Delivers 200–250 CFM Clean Air Delivery Rate (CADR), capturing 85%+ of airborne PM2.5 at 15% the cost of luxury purifiers."
        ))

        # 4. Low-Cost: Door & Window Weatherstripping (< $5)
        hacks.append(IAQHackItem(
            title="Friction Weatherstripping & Window Sash Sealing",
            cost_tier="Low-Cost (< $5)",
            materials_needed="Self-adhesive foam weatherstrip tape or silicone door bottom seal.",
            implementation_steps=(
                "1. Feel around window frames and door sills for cold drafts on smoggy mornings.\n"
                "2. Clean frame surfaces and apply self-adhesive foam strips along window meeting rails and door perimeters.\n"
                "3. Install a simple silicone wipe sweep along the bottom edge of main entrance doors."
            ),
            direct_impact="Reduces air infiltration rate from 0.8 ACH to 0.25 ACH, preventing 60% of outdoor smog infiltration."
        ))

        # 5. Equipment Tier (if user has budget)
        if profile.budget_tier == "equipment_ready":
            hacks.append(IAQHackItem(
                title="Strategic True HEPA Filter Placement & Continuous Operation",
                cost_tier="Equipment-Ready",
                materials_needed="True HEPA (H13) air purifier with CADR matched to room volume.",
                implementation_steps=(
                    "1. Position purifier at least 2 feet away from walls and curtains in the primary breathing zone.\n"
                    "2. Avoid running on maximum turbo for 10 minutes then shutting off; keep on medium speed 24/7 for steady air changes.\n"
                    "3. Ensure the pre-filter is vacuumed every 2 weeks to maintain motor efficiency and CADR."
                ),
                direct_impact="Maintains indoor PM2.5 below 15 µg/m³ (WHO target) regardless of outdoor hazardous conditions."
            ))

        return hacks

    def _build_sustainable_alternatives(self, profile: HouseholdProfile) -> List[SustainableAlternativeItem]:
        alts: List[SustainableAlternativeItem] = []

        # Commute swap
        if profile.commute_mode in ["car_alone", "two_wheeler"]:
            alts.append(SustainableAlternativeItem(
                title="Neighborhood School & Commute Carpooling Cluster",
                scope="Neighborhood/Community",
                replaces_activity="Individual solo car/two-wheeler runs for school drop-offs and office commutes.",
                direct_impact="Combines 3–4 separate vehicle trips into 1, reducing street congestion and avoiding 4.5–6.0 kg CO2e daily per cluster."
            ))
        else:
            alts.append(SustainableAlternativeItem(
                title="Active Metro / Bus Rapid Transit Corridor Use",
                scope="Household",
                replaces_activity="Occasional app-based cab or private auto trips.",
                direct_impact="Maintains 80% lower per-commuter greenhouse gas emissions compared to private vehicle transit."
            ))

        # Cooking/Heating swap
        if profile.cooking_heating in ["biomass_kerosene", "wood_coal"]:
            alts.append(SustainableAlternativeItem(
                title="Switch from Solid Biomass to Induction Cooktop / Electric Radiant Heating",
                scope="Household",
                replaces_activity="Indoor burning of wood, charcoal, dried dung cakes, or unvented kerosene heaters.",
                direct_impact="Eliminates the single largest source of extreme domestic PM2.5 and carbon monoxide exposure (>500 µg/m³ peak)."
            ))
        else:
            alts.append(SustainableAlternativeItem(
                title="Thermal Layering & Clean Electric Radiant Heating",
                scope="Household",
                replaces_activity="High-wattage continuous convection heating or decorative open fireplace use.",
                direct_impact="Zero point-source emissions indoors while trimming household winter energy demand by 15%."
            ))

        # Community Action: Leaf & Waste Management
        alts.append(SustainableAlternativeItem(
            title="Community Dry-Leaf Composting & Waste Biomass Ban",
            scope="Neighborhood/Community",
            replaces_activity="Open-air burning of fallen winter dry leaves and plastic/paper street litter.",
            direct_impact="A single neighborhood leaf pile fire produces more particulate matter than 10 idling diesel trucks over 2 hours. Composting turns waste into soil nutrients with zero smoke."
        ))

        # Community Action: Shared Clean Air Respite Center
        alts.append(SustainableAlternativeItem(
            title="Community Resident Welfare (RWA) Clean Air Sanctuary",
            scope="Neighborhood/Community",
            replaces_activity="Isolated household purifiers inaccessible to low-income neighbors, domestic workers, and street guards.",
            direct_impact="Equips community clubhouse or library with DIY box-fan filtration, providing a safe, filtered sanctuary for street workers and vulnerable neighbors."
        ))

        return alts

    def _build_direct_impacts(self, profile: HouseholdProfile, pm2_5: float) -> List[DirectImpactItem]:
        impacts: List[DirectImpactItem] = []

        # Commute impact
        commute_info = self.estimator.calculate_commute_impact(profile.commute_mode)
        impacts.append(DirectImpactItem(
            action=commute_info["action"],
            physical_mechanism=commute_info["physical_mechanism"],
            exposure_reduction=commute_info["exposure_reduction"],
            avoided_emissions=commute_info["avoided_emissions"],
            community_benefit=commute_info["community_benefit"]
        ))

        # IAQ Hacks impacts
        iaq_impacts = self.estimator.calculate_iaq_hacks_impact(profile.budget_tier, pm2_5)
        impacts.extend(iaq_impacts)

        # Diurnal routine impact
        routine_info = self.estimator.calculate_routine_inversion_impact(profile.time_of_day)
        impacts.append(DirectImpactItem(
            action=routine_info["action"],
            physical_mechanism=routine_info["physical_mechanism"],
            exposure_reduction=routine_info["exposure_reduction"],
            avoided_emissions=routine_info["avoided_emissions"],
            community_benefit=routine_info["community_benefit"]
        ))

        return impacts

    def evaluate_activity(
        self,
        activity: str,
        aqi_ctx: AirQualityContext,
        profile: HouseholdProfile
    ) -> ActivityEvaluationResponse:
        """
        Deterministic, science-grounded activity exposure and safety evaluator.
        Provides robust fallback when Gemini API is offline or unconfigured.
        """
        act_lower = (activity or "").lower()
        aqi = aqi_ctx.aqi
        pm2_5 = aqi_ctx.pm2_5

        # Feature keyword detection
        is_strenuous = any(k in act_lower for k in [
            "run", "jog", "sprint", "fast", "marathon", "cycling", "cycle", "bike",
            "cardio", "training", "workout", "exercise", "football", "cricket", "sports"
        ])
        is_outdoor = any(k in act_lower for k in [
            "outdoor", "park", "road", "street", "terrace", "balcony", "market",
            "recess", "playground", "run", "jog", "walk", "cycling", "commute"
        ]) and not ("indoor" in act_lower or "treadmill" in act_lower)
        is_ventilation = any(k in act_lower for k in ["ventilat", "window", "open door", "open window", "airing", "cross-vent"])
        is_cleaning = any(k in act_lower for k in ["sweep", "broom", "dust", "vacuum"])
        is_indoor_filtered = any(k in act_lower for k in ["indoor", "treadmill", "hepa", "filter", "air purifier", "sealed", "room", "home gym"])

        has_vulnerable = bool(profile.vulnerable_members)
        is_morning = any(k in act_lower for k in ["morning", "6", "7", "8", "9", "am", "dawn"]) or profile.time_of_day == "morning"

        # Special Case: Dry sweeping / dusting
        if is_cleaning and not ("wet" in act_lower or "damp" in act_lower or "mop" in act_lower):
            return ActivityEvaluationResponse(
                activity=activity,
                verdict="UNSAFE_AVOID",
                safety_score=28,
                risk_tier="High",
                exposure_mechanism=(
                    "Dry sweeping with conventional brooms mechanically resuspends settled thoracic particles (PM10 and PM2.5) "
                    "directly into breathing height, creating acute indoor spikes exceeding 350 µg/m³."
                ),
                actionable_mitigation="Never dry sweep during winter smog episodes. Wear an N95 mask if cleaning cannot be delayed.",
                safer_alternative="Switch to damp microfiber mopping or a sealed HEPA-filtered vacuum cleaner.",
                recommended_time_window="Afternoon hours (12:00–16:00) with indoor HEPA filtration active.",
                community_smog_impact="Prevents indoor fugitive dust from circulating to adjoining shared apartments.",
                non_medical_disclaimer=NON_MEDICAL_DISCLAIMER,
                generated_by="deterministic_safety_rules"
            )

        # Special Case: Window cross-ventilation during morning/severe smog
        if is_ventilation:
            if aqi >= 200 or (is_morning and aqi >= 100):
                return ActivityEvaluationResponse(
                    activity=activity,
                    verdict="UNSAFE_AVOID",
                    safety_score=15 if aqi >= 300 else 25,
                    risk_tier="Extreme" if aqi >= 300 else "High",
                    exposure_mechanism=(
                        f"Opening exterior apertures during nocturnal/morning temperature inversion allows outdoor ambient smog "
                        f"(PM2.5 {pm2_5} µg/m³) to rapidly equilibrate with indoor air via pressure gradients, erasing indoor clean air buffer."
                    ),
                    actionable_mitigation="Keep all external doors and windows hermetically sealed. Use draft sweeps along floor gaps.",
                    safer_alternative="Postpone brief (10-minute) cross-ventilation strictly to 13:00–15:00 when solar insolation elevates the mixing layer, then run purifiers on high.",
                    recommended_time_window="13:00 – 15:00 strictly (solar peak boundary layer mixing)",
                    community_smog_impact="Reduces building-wide infiltration and maintains purified indoor microclimates.",
                    non_medical_disclaimer=NON_MEDICAL_DISCLAIMER,
                    generated_by="deterministic_safety_rules"
                )
            else:
                return ActivityEvaluationResponse(
                    activity=activity,
                    verdict="CAUTION_WITH_RESTRICTIONS",
                    safety_score=60,
                    risk_tier="Moderate",
                    exposure_mechanism="Moderate outdoor particulate levels can enter, but lower ambient concentrations allow short ventilation cycles.",
                    actionable_mitigation="Limit open duration to 15 minutes, preferably with window mesh screen or pre-filter curtain.",
                    safer_alternative="Run indoor mechanical air purifiers / DIY Corsi-Rosenthal boxes for continuous air circulation without open windows.",
                    recommended_time_window="12:00 – 15:30",
                    community_smog_impact="Minimizes indoor pollution buildup naturally.",
                    non_medical_disclaimer=NON_MEDICAL_DISCLAIMER,
                    generated_by="deterministic_safety_rules"
                )

        # Indoor exercise or filtered room
        if is_indoor_filtered:
            score = 88 if aqi < 300 else 78
            verdict = "SAFE" if score >= 80 else "CAUTION_WITH_RESTRICTIONS"
            return ActivityEvaluationResponse(
                activity=activity,
                verdict=verdict,
                safety_score=score,
                risk_tier="Low" if score >= 80 else "Moderate",
                exposure_mechanism=(
                    "Enclosed indoor environments with air purifiers maintain 70–90% lower PM2.5 concentrations than outdoors. "
                    "Inhalation rate is elevated during exercise, but the purified indoor envelope protects alveolar membranes."
                ),
                actionable_mitigation="Verify door/window seals and run HEPA or DIY Corsi-Rosenthal unit on medium-high speed 30 minutes prior to exercise.",
                safer_alternative="Continue indoor exercise in sealed sanctuary room; avoid opening exterior balcony doors.",
                recommended_time_window="Anytime indoors with continuous active filtration.",
                community_smog_impact="Zero vehicle emissions generated; zero outdoor smog exposure.",
                non_medical_disclaimer=NON_MEDICAL_DISCLAIMER,
                generated_by="deterministic_safety_rules"
            )

        # Outdoor activities: evaluate based on exertion, AQI, time of day, and vulnerability
        if aqi >= 300:  # Severe
            verdict = "CRITICAL_HAZARD"
            score = 8 if is_strenuous else 18
            risk_tier = "Extreme"
            mech = (
                f"Severe ambient smog (AQI {aqi}, PM2.5 {pm2_5} µg/m³) during thermal boundary trapping. "
                + ("Strenuous aerobic breathing increases minute ventilation volume from 6 L/min to 60+ L/min, bypassing nasal filtration and causing deep alveolar deposition of toxic sulfates, nitrates, and black carbon." if is_strenuous else
                   "Walking or resting outdoors in severe smog exposes mucous membranes and airways to particulate levels over 20x WHO daily limits.")
            )
            mitigation = "If outdoor presence is strictly unavoidable, wear a certified, leak-free N95/FFP2 respirator. Limit outdoor duration to under 15 minutes."
            alt = "Shift workout or children's recess to a sealed indoor room with HEPA / DIY box-fan filtration."
            window = "Cancel outdoor session; reschedule indoors or postpone until severe inversion subsides."

        elif aqi >= 200:  # Very Poor
            verdict = "CRITICAL_HAZARD" if (is_strenuous or has_vulnerable) else "UNSAFE_AVOID"
            score = 18 if is_strenuous else 32
            risk_tier = "High"
            mech = (
                f"Very poor air quality (AQI {aqi}, PM2.5 {pm2_5} µg/m³). Outdoor exposure causes bronchial irritation, "
                "endothelial oxidative stress, and rapid asthma exacerbation in vulnerable family members."
            )
            mitigation = "Wear certified N95 respirator. Keep glasses/sunglasses on to minimize ocular particulate stinging."
            alt = "Replace outdoor training with indoor resistance, stretching, or treadmill workouts in a filtered room."
            window = "13:00 – 15:30 (solar thermal mixing provides marginal particulate dispersion; avoid morning 06:00–09:30 entirely)."

        elif aqi >= 100:  # Poor
            verdict = "UNSAFE_AVOID" if (is_strenuous and has_vulnerable) else "CAUTION_WITH_RESTRICTIONS"
            score = 45 if is_strenuous else 58
            risk_tier = "Moderate"
            mech = (
                f"Poor air quality (AQI {aqi}). Moderate particulate inhalation can trigger coughing, throat tickle, "
                "and reduced peak expiratory flow rate during sustained outdoor exertion."
            )
            mitigation = "Wear a well-fitted N95 mask. Reduce exercise intensity to low-moderate walking."
            alt = "Move cardio training indoors; schedule casual outdoor errands for early afternoon."
            window = "12:00 – 16:00 (optimal vertical atmospheric dispersion window)."

        else:  # Moderate / Acceptable
            verdict = "CAUTION_WITH_RESTRICTIONS" if has_vulnerable else "SAFE"
            score = 72 if is_strenuous else 85
            risk_tier = "Low"
            mech = f"Moderate air quality (AQI {aqi}). Normal healthy individuals experience low acute risk; sensitive respiratory cohorts may feel slight throat irritation."
            mitigation = "Sensitive individuals (asthma/elderly) should carry rescue inhalers and avoid prolonged heavy exertion."
            alt = "Enjoy moderate outdoor activities during midday hours."
            window = "11:00 – 16:30"

        return ActivityEvaluationResponse(
            activity=activity,
            verdict=verdict,
            safety_score=score,
            risk_tier=risk_tier,
            exposure_mechanism=mech,
            actionable_mitigation=mitigation,
            safer_alternative=alt,
            recommended_time_window=window,
            community_smog_impact="Avoiding motorized solo car travel for this activity cuts community NOx and primary soot emissions.",
            non_medical_disclaimer=NON_MEDICAL_DISCLAIMER,
            generated_by="deterministic_safety_rules"
        )

